import{z as h,x as B,o as e,c as l,q as E,j as n,D as t,d as r,s as o,S as m,b as i}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"Girsanov 测度变换","description":"","frontmatter":{"title":"Girsanov 测度变换","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/girsanov-measure.md","filePath":"quant/girsanov-measure.md","lastUpdated":1791063341000}'),d={name:"quant/girsanov-measure.md"};function A(p,a,u,_,D,v){const s=B("Mermaid");return e(),l("div",null,[a[2]||(a[2]=E('<h1 id="girsanov-测度变换" tabindex="-1">Girsanov 测度变换 <a class="header-anchor" href="#girsanov-测度变换" aria-label="Permalink to &quot;Girsanov 测度变换&quot;">​</a></h1><div class="epigraph"><p>Girsanov 用指数鞅改布朗的漂移：在 $Q$ 下，$W^Q_t=W_t+\\int_0^t\\theta_s\\,\\mathrm d s$ 仍是布朗运动。</p><footer>—— 据 Girsanov, Theory of Probability and Its Applications, 1960；Karatzas and Shreve, 1991, §3.5；Shreve, Stochastic Calculus for Finance II, 第 5 章整理</footer></div><p>上一课<a href="/quant/radon-nikodym">Radon–Nikodym 导数</a>给出抽象密度 \\(\\xi\\)。缺口是布朗运动上的具体形状：要让 \\(\\mathrm d S=\\mu S\\,\\mathrm d t+\\sigma S\\,\\mathrm d W\\) 在新测度下变成 \\(\\mathrm d S=r S\\,\\mathrm d t+\\sigma S\\,\\mathrm d W^Q\\)，密度必须把漂移移动 \\(\\theta=(\\mu-r)/\\sigma\\)。本课只给出这条变换，并留下 Novikov 条件；「为何选这个 \\(\\theta\\)」是下一课风险中性的经济内容。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RN 密度可以是任意正鞅。对布朗信息流，连续正鞅由随机指数给出。缺口是：选定过程 \\(\\theta\\)，令</p> \\[\\xi_t=\\exp\\Bigl(-\\int_0^t\\theta_s\\,\\mathrm d W_s-\\tfrac12\\int_0^t\\theta_s^2\\,\\mathrm d s\\Bigr), \\]<p>在 \\(\\xi\\) 为鞅时定义 \\(Q\\)，证明 \\(W^Q=W+\\int\\theta\\) 在 \\(Q\\) 下是标准布朗。没有这条，换测度只改期望权重，不改路径的漂移语言。</p><p>\\(\\theta\\) 叫市场的风险的市场价格（下一课才命名）。本课只把它当作漂移平移的旋钮。</p><h3 id="girsanov-不改变波动率" tabindex="-1">Girsanov 不改变波动率 <a class="header-anchor" href="#girsanov-不改变波动率" aria-label="Permalink to &quot;Girsanov 不改变波动率&quot;">​</a></h3><p>二次变差是路径性质，\\([W]_t=t\\) 在等价测度下不变。因此 \\(\\sigma\\) 不随 \\(P\\to Q\\) 改变；变的只是 \\(\\mathrm d t\\) 项。把「风险中性」理解成「波动率换成别的数」，是把测度和模型校准混在一起。校准是<a href="/quant/vol-as-input">波动率是输入不是输出</a>的事。</p><p><span class="marginnote">Novikov：\\(\\mathbb E\\exp(\\tfrac12\\int\\theta^2)\\lt \\infty\\) 则指数局部鞅是真鞅。实践中常对有界 \\(\\theta\\) 直接用；无界时要核验，否则 \\(Q\\) 甚至不是概率。</span></p><p><span class="marginnote">为什么需要 Novikov？指数若只是局部鞅，期望可能小于 1，这时 \\(Q(A)=\\mathbb E[\\xi_T 1_A]\\) 对全体事件加起来不足 1，\\(Q\\) 就不成其为概率测度。Novikov 条件是常用的保险丝：\\(\\theta\\) 有界时自动满足；\\(\\theta\\) 无界（如随波动率爆炸）时必须单独核验，否则后面的定义全部悬空。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设 \\(\\theta\\) 适应、\\(\\int_0^T\\theta^2\\lt \\infty\\) a.s.，且 \\(\\xi\\) 为 \\(P\\)-鞅。定义 \\(Q(A)=\\mathbb E_P[\\xi_T 1_A]\\)。则 \\(W^Q_t=W_t+\\int_0^t\\theta_s\\,\\mathrm d s\\) 是 \\(Q\\)-布朗运动（至 \\(T\\)）。SDE \\(\\mathrm d X=\\mu\\,\\mathrm d t+\\sigma\\,\\mathrm d W\\) 改写为 \\(\\mathrm d X=(\\mu-\\sigma\\theta)\\,\\mathrm d t+\\sigma\\,\\mathrm d W^Q\\)。多维时 \\(\\theta\\) 是向量，\\(\\sigma\\theta\\) 是矩阵乘积；\\(\\sigma\\) 不满秩时不是任意漂移都能消掉——那是不全市场课的缺口。</p><p>Itô 公式在 \\(Q\\) 下对 \\(W^Q\\) 照常使用，因为 \\(W^Q\\) 仍是布朗。密度过程满足 \\(\\mathrm d\\xi=-\\theta\\xi\\,\\mathrm d W\\)，无漂移，与上一课「密度是 \\(P\\)-鞅」一致。</p><p><span class="marginnote">数字实例：取 \\(\\mu=8\\%\\)、\\(r=3\\%\\)、\\(\\sigma=20\\%\\)，则 \\(\\theta=(0.08-0.03)/0.2=0.25\\)。换到 \\(Q\\) 后漂移被平移 \\(\\sigma\\theta=5\\) 个百分点，恰好从 8% 变成 3%。这个 0.25 度量「每一单位波动率里藏着多少风险溢价」，下一课称它为风险的市场价格。</span></p>',16)),(e(),n(m,null,{default:t(()=>[o(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20THETA%5B%22%E8%BF%87%E7%A8%8B%20theta%22%5D%20--%3E%20XI%5B%22%E6%8C%87%E6%95%B0%E5%AF%86%E5%BA%A6%22%5D%0A%20%20XI%20--%3E%20Q%5B%22%E7%AD%89%E4%BB%B7%E6%B5%8B%E5%BA%A6%20Q%22%5D%0A%20%20Q%20--%3E%20WQ%5B%22W%20%E5%8A%A0%E7%A7%AF%E5%88%86%20theta%20%E6%98%AF%20Q%20%E5%B8%83%E6%9C%97%22%5D%0A%20%20WQ%20--%3E%20DRIFT%5B%22%E6%BC%82%E7%A7%BB%E5%B9%B3%E7%A7%BB%20sigma%20theta%22%5D%0A%20%20DRIFT%20--%3E%20RN%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E9%A3%8E%E9%99%A9%E4%B8%AD%E6%80%A7%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[r("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"指数里的 \\(-\\tfrac12\\int\\theta^2\\) 又是 Itô 修正：\\(\\mathrm e^{-\\int\\theta\\,\\mathrm d W}\\) 单独不是鞅。Girsanov 的核心计算是：把 \\(W^Q\\) 的特征函数在 \\(Q\\) 下用 \\(\\xi\\) 写回 \\(P\\)，认出独立高斯增量。直观上，乘 \\(\\xi\\) 给那些沿 \\(\\theta\\) 方向走得更远的路径更大权重，等效于把均值平移。",-1)),(e(),n(m,null,{default:t(()=>[o(s,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%9C%9F%E5%AE%9E%E6%B5%8B%E5%BA%A6%20P%20%E4%B8%8B%E7%9A%84%E5%90%8C%E4%B8%80%E6%89%B9%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20W%7B%22%E7%BB%99%E6%AF%8F%E6%9D%A1%E8%B7%AF%E5%BE%84%E4%B9%98%E6%9D%83%E9%87%8D%20%CE%BE%22%7D%0A%20%20W%20--%3E%7C%22%E9%80%86%E7%9D%80%20%CE%B8%20%E6%96%B9%E5%90%91%E8%B5%B0%22%7C%20Down%5B%22%E6%9D%83%E9%87%8D%E5%8F%98%E5%B0%8F%22%5D%0A%20%20W%20--%3E%7C%22%E9%A1%BA%E7%9D%80%20%CE%B8%20%E8%B5%B0%E5%BE%97%E6%9B%B4%E8%BF%9C%22%7C%20Up%5B%22%E6%9D%83%E9%87%8D%E5%8F%98%E5%A4%A7%22%5D%0A%20%20Down%20--%3E%20Eff%5B%22%E5%8A%A0%E6%9D%83%E5%B9%B3%E5%9D%87%E4%BD%8D%E7%BD%AE%E6%95%B4%E4%BD%93%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20Up%20--%3E%20Eff%0A%20%20Eff%20--%3E%20QQ%5B%22%E7%AD%89%E6%95%88%E4%BA%8E%20Q%20%E4%B8%8B%E6%BC%82%E7%A7%BB%E8%A2%AB%E5%B9%B3%E7%A7%BB%20%CF%83%CE%B8%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=E('<p><span class="marginnote">把测度变换想成给同一批路径「重新投票」：路径集合一条没少，变的只是每条路径的话语权。顺着 \\(\\theta\\) 方向走得远的路径被投更多票，加权后的平均路径因此平移。这就是「乘 \\(\\xi\\) 等效于改漂移」的直观版——没有删路径，只有权重换了。</span></p><p>波动率矩阵决定能平移的漂移子空间。\\(\\theta\\) 的个数不能超过独立布朗的个数——市场有多少噪声源，就能对冲多少风险溢价。本课只把线性代数接口留下。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Girsanov–Meyer 对半鞅的一般形式，不讨论无穷时间区间上的一致性。跳过程的 Esscher 变换是另一套密度，留给跳课预览。后课默认：改布朗漂移 = 选 \\(\\theta\\) 做指数鞅；\\(\\sigma\\) 不变。下一课<a href="/quant/risk-neutral-measure">风险中性测度</a>把 \\(\\theta\\) 选成使贴现标的为鞅的那个。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Girsanov 用指数鞅平移布朗漂移，\\(W^Q=W+\\int\\theta\\)。</li><li>波动率（二次变差）在等价测度下不变。</li><li>Novikov 把指数局部鞅升级为密度。</li><li>\\(\\mu\\mapsto\\mu-\\sigma\\theta\\) 是 SDE 在 \\(Q\\) 下的全部变化。</li><li>出处：Girsanov 1960；Karatzas–Shreve §3.5；Shreve SDE II 第 5 章。</li></ul>',6))])}const g=h(d,[["render",A]]);export{c as __pageData,g as default};
